import threading
import sys
from ta_messaging import message_manager
from abc import abstractproperty
from ta_messaging.submodule_ute_common_abstract_core.aliases_registry import aliases_registry
from ute_common_abstract_core.scope import current_scope

if sys.version_info[0] >= 3:
    from queue import Queue, Empty
else:
    from Queue import Queue, Empty


class MessagesSubscriber(object):
    """
    Class for subscribing for messages letting user e.g count them
    """
    def __init__(self):
        self.queue_for_messages = Queue()
        self.dequeue_timeout = 0.01
        self._manager = message_manager.MessageManager()
        self.subscribed = False
        self._is_running = threading.Event()
        self._is_ended = threading.Semaphore()
        self._is_started = threading.Semaphore()
        self._start_reading_queue_in_separate_thread()
        self._is_started.acquire()

    def _start_reading_queue_in_separate_thread(self):
        threading.Thread(target=self._get_messages).start()
        current_scope().uses(self, self.__class__.stop)

    def stop(self):
        """

        :return:
        """
        if self._is_running.is_set():
            self._manager.dispatcher.unsubscribe_observer(self.queue_for_messages)
            self._is_running.clear()
            self._is_ended.acquire()

    def _get_messages(self):
        self._is_running.set()
        self._is_started.release()
        while self._is_running.is_set():
            try:
                msg = self.queue_for_messages.get(timeout=self.dequeue_timeout)
                self.on_new_message(msg)
            except Empty:
                pass
        self._is_ended.release()

    @abstractproperty
    def on_new_message(self, message):
        """
        Defines action that should be done when new message arrives
        """

    def _subscribe(self, owner):
        if self.subscribed:
            print('Can subscribe only once per counter, create another counter')
            return
        self._manager.dispatcher.subscribe_observer(self.queue_for_messages, message_type=None, owner=owner)
        self.subscribed = True

    def subscribe_all(self):
        """

        :return:
        """
        self._subscribe(owner=None)

    def subscribe_ue(self, alias):
        """
        Allows subscription for messages from specific UE
        :param alias: UE alias, e.g. UE_1
        :return:
        """
        alias_for_ue_identification = alias + "__identification"
        network_element = aliases_registry()[alias_for_ue_identification]
        self._subscribe(owner=network_element.network_elem_identifier)

    def subscribe_cell(self, alias):
        """
        Allows subscription for messages from specific cell
        :param alias: cell alias, e.g. CELL_1
        :return:
        """
        alias_for_cell_identification = alias + "__identification"
        network_element = aliases_registry()[alias_for_cell_identification]
        self._subscribe(owner=network_element.network_elem_identifier)

    def subscribe_mme(self, alias):
        """
        Allows subscription for messages from MME
        :param alias: mme alias, e.g. MME_1
        :return:
        """
        network_element = aliases_registry()[alias]
        self._subscribe(owner=network_element.network_elem_identifier)

    def subscribe_enb(self, alias):
        """
        Allows subscription for messages from eNB
        :param alias: eNB alias, e.g. ENB_1
        :return:
        """
        network_element = aliases_registry()[alias]
        self._subscribe(owner=network_element.network_elem_identifier)
